import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);StringTokenizer st = new StringTokenizer(br.readLine());int t = Integer.parseInt(st.nextToken());while (t-- > 0) {st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int maxDivisor = 1;for (int i = 2; i * i <= n; i++) {if (n % i == 0) {maxDivisor = n / i;break;}}out.println(maxDivisor + " " + (n - maxDivisor));}out.flush();out.close();}}